useEffect(()=>{load();const client=supabase;if(!client)return;const ch=client.channel('merchant-'+userId).on('postgres_changes',{event:'*',schema:'public',table:'orders'},()=>load()).on('postgres_changes',{event:'*',schema:'public',table:'products'},()=>load()).subscribe();return()=>{client.removeChannel(ch)}},[load,userId]);
