  if(profileError){M('تعذر قراءة بيانات الأطراف: '+profileError.message);return}
  const profileMap=new Map((profiles||[]).map((x:any)=>[x.id,x]));
  const users=new Map(((userData?.users||[]) as any[]).map(x=>[x.id,x]));
  const year=new Date().getFullYear();
  const driverPayloads=(apps||[]).map((a:any)=>{
   const p:any=profileMap.get(a.user_id)||{},u:any=users.get(a.user_id)||{};
   return {contract_number:'ASE-D-'+year+'-'+String(a.user_id).replace(/-/g,'').slice(0,10).toUpperCase(),contract_type:'driver',subject_user_id:a.user_id,subject_name:p.full_name||u.full_name||'سائق عين صالح',subject_email:u.email||'',subject_phone:p.phone||u.phone||'',subject_address:'عين صالح، الجزائر',status:a.status==='approved'?'issued':'draft',terms:{template_key:'driver',template_version:LEGAL_TEMPLATE_VERSION,application_status:a.status,vehicle_type:a.vehicle_type||'غير محدد',vehicle_description:a.vehicle_description||'',auto_generated:true}};
  });
  const merchantPayloads=(stores||[]).map((s:any)=>{
   const p:any=profileMap.get(s.owner_id)||{},u:any=users.get(s.owner_id)||{};
   return {contract_number:'ASE-M-'+year+'-'+String(s.owner_id).replace(/-/g,'').slice(0,10).toUpperCase(),contract_type:'merchant',subject_user_id:s.owner_id,store_id:s.id,subject_name:s.name||p.full_name||'متجر شريك',subject_email:u.email||'',subject_phone:s.phone||p.phone||u.phone||'',subject_address:s.address||'عين صالح، الجزائر',status:'draft',terms:{template_key:'merchant',template_version:LEGAL_TEMPLATE_VERSION,category:s.category||'',description:s.description||'',auto_generated:true}};
  });
  const payloads=[...driverPayloads,...merchantPayloads];
  if(!payloads.length)return;
